import{_ as t,c as s,o as i,j as n,Y as o,t as r}from"./chunks/framework.D-NV0Bun.js";const g=JSON.parse('{"title":"docker-container-update | x-cmd man (docker man1) | Update configuration of one or more containers","titleTemplate":false,"description":"x-cmd man (docker man1 Manual Page) | docker-container-update - Update configuration of one or more containers","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"docker-container-update | x-cmd man (docker man1) | Update configuration of one or more containers"}],["meta",{"name":"og:description","content":"x-cmd man (docker man1 Manual Page) | docker-container-update - Update configuration of one or more containers"}]]},"headers":[],"params":{"isMan":true,"man":"docker-container-update","category":"docker man1","desc":"Update configuration of one or more containers"},"relativePath":"docker/man1/docker-container-update.md","filePath":"docker/man1/[man].md"}'),p={name:"docker/man1/docker-container-update.md"},h={class:"visually-hidden"};function l(a,e,d,c,m,k){return i(),s("div",null,[n("h1",h,r(a.$params.man),1),e[0]||(e[0]=o('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>docker-container-update - Update configuration of one or more containers</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>docker container update [OPTIONS] CONTAINER [CONTAINER...]</strong></p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>The <strong>docker container update</strong> command dynamically updates container configuration. You can use this command to prevent containers from consuming too many resources from their Docker host. With a single command, you can place limits on a single container or on many. To specify more than one container, provide space-separated list of container names or IDs.</p><p>With the exception of the <strong>--kernel-memory</strong> option, you can specify these options on a running or a stopped container. On kernel version older than 4.6, You can only update <strong>--kernel-memory</strong> on a stopped container or on a running container with kernel memory initialized.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><h2 id="kernel-memory" tabindex="-1">kernel-memory <a class="header-anchor" href="#kernel-memory" aria-label="Permalink to &quot;kernel-memory&quot;">​</a></h2><p>Kernel memory limit (format: <strong>&lt;number&gt;[&lt;unit&gt;]</strong>, where unit = b, k, m or g)</p><p>Note that on kernel version older than 4.6, you can not update kernel memory on a running container if the container is started without kernel memory initialized, in this case, it can only be updated after it&#39;s stopped. The new setting takes effect when the container is started.</p><h2 id="memory" tabindex="-1">memory <a class="header-anchor" href="#memory" aria-label="Permalink to &quot;memory&quot;">​</a></h2><p>Memory limit (format: , where unit = b, k, m or g)</p><p>Note that the memory should be smaller than the already set swap memory limit. If you want update a memory limit bigger than the already set swap memory limit, you should update swap memory limit at the same time. If you don&#39;t set swap memory limit on docker create/run but only memory limit, the swap memory is double the memory limit.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p>The following sections illustrate ways to use this command.</p><h3 id="update-a-container-s-cpu-shares" tabindex="-1">Update a container&#39;s cpu-shares <a class="header-anchor" href="#update-a-container-s-cpu-shares" aria-label="Permalink to &quot;Update a container\\&#39;s cpu-shares&quot;">​</a></h3><p>To limit a container&#39;s cpu-shares to 512, first identify the container name or ID. You can use <strong>docker ps</strong> to find these values. You can also use the ID returned from the <strong>docker run</strong> command. Then, do the following:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> container</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cpu-shares</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 512</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> abebf7571666</span></span></code></pre></div><h3 id="update-a-container-with-cpu-shares-and-memory" tabindex="-1">Update a container with cpu-shares and memory <a class="header-anchor" href="#update-a-container-with-cpu-shares-and-memory" aria-label="Permalink to &quot;Update a container with cpu-shares and memory&quot;">​</a></h3><p>To update multiple resource configurations for multiple containers:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> container</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cpu-shares</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 512</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 300M</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> abebf7571666</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hopeful_morse</span></span></code></pre></div><h3 id="update-a-container-s-kernel-memory-constraints" tabindex="-1">Update a container&#39;s kernel memory constraints <a class="header-anchor" href="#update-a-container-s-kernel-memory-constraints" aria-label="Permalink to &quot;Update a container\\&#39;s kernel memory constraints&quot;">​</a></h3><p>You can update a container&#39;s kernel memory limit using the <strong>--kernel-memory</strong> option. On kernel version older than 4.6, this option can be updated on a running container only if the container was started with <strong>--kernel-memory</strong>. If the container was started <em>without</em> <strong>--kernel-memory</strong> you need to stop the container before updating kernel memory.</p><p>NOTE: The <strong>--kernel-memory</strong> option has been deprecated since Docker 20.10.</p><p>For example, if you started a container with this command:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -dit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --kernel-memory</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 50M</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ubuntu</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span></span></code></pre></div><p>You can update kernel memory while the container is running:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> container</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --kernel-memory</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 80M</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>If you started a container <em>without</em> kernel memory initialized:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -dit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --memory</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 300M</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ubuntu</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span></span></code></pre></div><p>Update kernel memory of running container <strong>test2</strong> will fail. You need to stop the container before updating the <strong>--kernel-memory</strong> setting. The next time you start it, the container uses the new value.</p><p>Kernel version newer than (include) 4.6 does not have this limitation, you can use <strong>--kernel-memory</strong> the same way as other options.</p><h3 id="update-a-container-s-restart-policy" tabindex="-1">Update a container&#39;s restart policy <a class="header-anchor" href="#update-a-container-s-restart-policy" aria-label="Permalink to &quot;Update a container\\&#39;s restart policy&quot;">​</a></h3><p>You can change a container&#39;s restart policy on a running container. The new restart policy takes effect instantly after you run <strong>docker container update</strong> on a container.</p><p>To update restart policy for one or more containers:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> container</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --restart=on-failure:3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> abebf7571666</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hopeful_morse</span></span></code></pre></div><p>Note that if the container is started with &quot;--rm&quot; flag, you cannot update the restart policy for it. The <strong>AutoRemove</strong> and <strong>RestartPolicy</strong> are mutually exclusive for the container.</p><h2 id="options-1" tabindex="-1">OPTIONS <a class="header-anchor" href="#options-1" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p><strong>--blkio-weight</strong>=0 Block IO (relative weight), between 10 and 1000, or 0 to disable (default 0)</p><p><strong>--cpu-period</strong>=0 Limit CPU CFS (Completely Fair Scheduler) period</p><p><strong>--cpu-quota</strong>=0 Limit CPU CFS (Completely Fair Scheduler) quota</p><p><strong>--cpu-rt-period</strong>=0 Limit the CPU real-time period in microseconds</p><p><strong>--cpu-rt-runtime</strong>=0 Limit the CPU real-time runtime in microseconds</p><p><strong>-c</strong>, <strong>--cpu-shares</strong>=0 CPU shares (relative weight)</p><p><strong>--cpus</strong>= Number of CPUs</p><p><strong>--cpuset-cpus</strong>=&quot;&quot; CPUs in which to allow execution (0-3, 0,1)</p><p><strong>--cpuset-mems</strong>=&quot;&quot; MEMs in which to allow execution (0-3, 0,1)</p><p><strong>-h</strong>, <strong>--help</strong>[=false] help for update</p><p><strong>-m</strong>, <strong>--memory</strong>=0 Memory limit</p><p><strong>--memory-reservation</strong>=0 Memory soft limit</p><p><strong>--memory-swap</strong>=0 Swap limit equal to memory plus swap: -1 to enable unlimited swap</p><p><strong>--pids-limit</strong>=0 Tune container pids limit (set -1 for unlimited)</p><p><strong>--restart</strong>=&quot;&quot; Restart policy to apply when a container exits</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>docker-container(1)</strong></p>',56))])}const y=t(p,[["render",l]]);export{g as __pageData,y as default};
